    confirmAction('Verifikasi pendaftaran ini dan <strong>buat akun siswa</strong>?', function() {
        btn.disabled = true;
        btn.innerHTML = '<span class="spinner-border spinner-border-sm me-1"></span>Memproses...';
        fetch(`${_regVerifyUrl}/${id}/verify`, {
            method: 'POST',
